-- Permission vocabulary and system roles of the payment-gateway module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the payment-gateway permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('gateway_transaction:create'::text, 'gateway_transaction'::text, 'create'::text, 'Create gateway transaction'::text),
            ('gateway_transaction:delete'::text, 'gateway_transaction'::text, 'delete'::text, 'Delete gateway transaction'::text),
            ('gateway_transaction:purge'::text, 'gateway_transaction'::text, 'purge'::text, 'Purge gateway transaction'::text),
            ('gateway_transaction:read'::text, 'gateway_transaction'::text, 'read'::text, 'Read gateway transaction'::text),
            ('gateway_transaction:restore'::text, 'gateway_transaction'::text, 'restore'::text, 'Restore gateway transaction'::text),
            ('gateway_transaction:update'::text, 'gateway_transaction'::text, 'update'::text, 'Update gateway transaction'::text),
            ('payment_gateway_provider:create'::text, 'payment_gateway_provider'::text, 'create'::text, 'Create payment gateway provider'::text),
            ('payment_gateway_provider:delete'::text, 'payment_gateway_provider'::text, 'delete'::text, 'Delete payment gateway provider'::text),
            ('payment_gateway_provider:purge'::text, 'payment_gateway_provider'::text, 'purge'::text, 'Purge payment gateway provider'::text),
            ('payment_gateway_provider:read'::text, 'payment_gateway_provider'::text, 'read'::text, 'Read payment gateway provider'::text),
            ('payment_gateway_provider:restore'::text, 'payment_gateway_provider'::text, 'restore'::text, 'Restore payment gateway provider'::text),
            ('payment_gateway_provider:update'::text, 'payment_gateway_provider'::text, 'update'::text, 'Update payment gateway provider'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('gateway_transaction:create'::text, 'gateway_transaction'::text, 'create'::text, 'Create gateway transaction'::text),
            ('gateway_transaction:delete'::text, 'gateway_transaction'::text, 'delete'::text, 'Delete gateway transaction'::text),
            ('gateway_transaction:purge'::text, 'gateway_transaction'::text, 'purge'::text, 'Purge gateway transaction'::text),
            ('gateway_transaction:read'::text, 'gateway_transaction'::text, 'read'::text, 'Read gateway transaction'::text),
            ('gateway_transaction:restore'::text, 'gateway_transaction'::text, 'restore'::text, 'Restore gateway transaction'::text),
            ('gateway_transaction:update'::text, 'gateway_transaction'::text, 'update'::text, 'Update gateway transaction'::text),
            ('payment_gateway_provider:create'::text, 'payment_gateway_provider'::text, 'create'::text, 'Create payment gateway provider'::text),
            ('payment_gateway_provider:delete'::text, 'payment_gateway_provider'::text, 'delete'::text, 'Delete payment gateway provider'::text),
            ('payment_gateway_provider:purge'::text, 'payment_gateway_provider'::text, 'purge'::text, 'Purge payment gateway provider'::text),
            ('payment_gateway_provider:read'::text, 'payment_gateway_provider'::text, 'read'::text, 'Read payment gateway provider'::text),
            ('payment_gateway_provider:restore'::text, 'payment_gateway_provider'::text, 'restore'::text, 'Restore payment gateway provider'::text),
            ('payment_gateway_provider:update'::text, 'payment_gateway_provider'::text, 'update'::text, 'Update payment gateway provider'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
